document.getElementById("theme").onclick=()=>{const e=document.documentElement;e.dataset.theme="light"===e.dataset.theme?"dark":"light";try{localStorage.setItem("dh-theme",e.dataset.theme)}catch(e){}},document.querySelectorAll("[data-zoom]").forEach(e=>e.addEventListener("click",()=>{const t=document.getElementById("lb");t.querySelector("img").src=e.dataset.zoom,t.querySelector("img").alt=e.alt,t.querySelector("p").textContent=e.alt,t.showModal()}));const lb=document.getElementById("lb");lb&&lb.addEventListener("click",e=>{e.target!==lb&&"BUTTON"!==e.target.tagName||lb.close()});const vio=new IntersectionObserver(e=>e.forEach(e=>{const t=e.target;e.isIntersecting?(t.src||(t.src=t.dataset.src),t.play().catch(()=>{})):t.pause()}),{threshold:.35});document.querySelectorAll("video[data-src]").forEach(e=>vio.observe(e));const vs=[...document.querySelectorAll(".vids video")];vs.forEach(e=>e.addEventListener("play",()=>vs.forEach(t=>t!==e&&t.pause())));